'use client'

import * as React from 'react'

// Anyone the host can name is rendered by `identity`, never by this file: the
// avatar cases, the presence dot and the accessible name are decided there.
import { Identity, type IdentityPlayer, type IdentityPresence } from './identity'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Presence, and `tsc --noEmit` passes on it, so
// the gate cannot catch it.
import './presence.css'

/**
 * Presence: you are not alone.
 *
 * Two facts, from specimen 4h, each drawn as its own pill. How many people are
 * here, which is a number a player tracks and rides `data-gs-value`: the
 * drawing puts four coloured symbols in front of it, "symbols, not avatars,
 * when unknown", and a live dot after it. And which of them the host can name,
 * each one an `identity`: the drawing stacks their avatars and says it in one
 * sentence, "Sam and Priya are in".
 *
 * **It subscribes to nothing.** It opens no socket, polls no endpoint and
 * counts nobody. The host knows who is here and hands the number and the list
 * over; a count that changes is the host re-rendering it.
 *
 * Naming somebody is the host's decision and its consent to make: the design's
 * rule is names only with consent, so this renders exactly the entries it is
 * given and never infers one from a count.
 *
 * The case that matters is the quiet one. A game nobody else is playing is the
 * first thing an early arrival sees, and a room that renders nothing at all
 * reads as a component that failed to load, so nought carries
 * `data-gs-empty="true"` and a designed line.
 */

/** One person the host can name, and what is true of them. */
export interface PresenceEntry {
  /** Who they are. Passed straight to `identity`. */
  player: IdentityPlayer
  /** Whether they are here now. The host knows; this never asks. */
  presence?: IdentityPresence
  /** This is the player holding the device. */
  you?: boolean
}

export interface PresenceProps extends Omit<React.HTMLAttributes<HTMLDivElement>, 'children'> {
  /**
   * How many people are here, the host's number. Absent means the host does not
   * know, which is not the same as nobody: the count is left out rather than
   * rendered as a nought.
   */
  count?: number
  /** The words beside the number. Also how the default localises. */
  label?: string
  /** The people the host can name, in the host's order. This never sorts. */
  entries?: PresenceEntry[]
  /** Render the count as something other than the bare number, e.g. `1,204`. */
  format?: (count: number) => string
  /** The line a player reads when there is nobody else here yet. */
  emptyLabel?: string
  /**
   * The sentence beside the named people: "Sam and Priya are in". Takes their
   * names in the host's order, so a host that localises writes its own.
   */
  namesLabel?: (names: string[]) => string
  /** Whatever the host puts beside it: an invite control, a share sheet. */
  children?: React.ReactNode
}

/** The contract's word for `data-gs-empty`, in the name and on the screen. */
const EMPTY_LABEL = 'nothing here yet'

/** The default words beside the number. */
const DEFAULT_LABEL = 'playing now'

/** "Sam is in", "Sam and Priya are in", "Sam, Priya and Ada are in". */
function defaultNamesLabel(names: string[]): string {
  if (names.length === 0) return ''
  if (names.length === 1) return `${names[0]} is in`
  return `${names.slice(0, -1).join(', ')} and ${names[names.length - 1]} are in`
}

/**
 * The four symbols in front of the count. Symbols, not avatars: the drawing
 * colours them player, opponent, warning and positive, and they stand for the
 * room rather than for anybody in it.
 */
const SYMBOLS = ['player', 'opponent', 'warning', 'positive'] as const

export function Presence({
  count,
  label = DEFAULT_LABEL,
  entries = [],
  format,
  emptyLabel = EMPTY_LABEL,
  namesLabel = defaultNamesLabel,
  children,
  className,
  ...rest
}: PresenceProps) {
  // Nobody here is a state; nobody known is not. A host that knows only the
  // count still has a room full of people.
  const empty = count === 0 && entries.length === 0
  const rendered = count === undefined ? undefined : format ? format(count) : String(count)

  // What it is, then how many, then the state. The entries below carry their
  // own names and stay announced, so they are not repeated here.
  const words = empty
    ? [label, EMPTY_LABEL]
    : rendered === undefined
      ? [label]
      : [label, rendered]

  return (
    <div
      {...rest}
      className={['gs-presence', className].filter(Boolean).join(' ')}
      data-gs-component="presence"
      data-gs-value={count}
      data-gs-empty={empty ? 'true' : undefined}
      role="group"
      aria-label={words.join(', ')}
    >
      <p className="gs-presence__count">
        {empty ? null : (
          <span className="gs-presence__symbols" data-gs-scope="presence" data-gs-part="marks" aria-hidden="true">
            {SYMBOLS.map((symbol) => (
              <span key={symbol} className={`gs-presence__symbol gs-presence__symbol--${symbol}`} />
            ))}
          </span>
        )}
        <span className="gs-presence__words" aria-hidden="true">
          {rendered === undefined ? null : (
            <span className="gs-presence__value" data-gs-scope="presence" data-gs-part="value">
              {rendered}
            </span>
          )}
          <span className="gs-presence__label" data-gs-scope="presence" data-gs-part="label">
            {empty ? emptyLabel : label}
          </span>
        </span>
        {/* The room's own dot. It pulses, so it is motion and stops dead under
            reduced motion, where the dot is still there and still says live. */}
        <span
          className="gs-presence__live"
          data-gs-scope="presence"
          data-gs-part="presence"
          data-gs-motion="pulse"
          data-gs-animates="motion"
          aria-hidden="true"
        />
      </p>

      {entries.length === 0 ? null : (
        <div className="gs-presence__named">
          {/* A real list, so a screen reader is told how many names there are
              before reading them. Each identity keeps its own name; only the
              avatars show, stacked, and the sentence beside them says who. */}
          <ul className="gs-presence__list" data-gs-scope="presence" data-gs-part="list">
            {entries.map((entry) => (
              <li className="gs-presence__row" data-gs-scope="presence" data-gs-part="row" key={entry.player.id}>
                <Identity
                  player={entry.player}
                  presence={entry.presence}
                  you={entry.you}
                  size="small"
                />
              </li>
            ))}
          </ul>
          {/* Only the people the host named by name go in the sentence; one
              without a display name is still in the list and still announced
              by identity under its own fallback. */}
          <span className="gs-presence__summary" data-gs-scope="presence" data-gs-part="summary" aria-hidden="true">
            {namesLabel(
              entries
                .map((entry) => entry.player.displayName?.trim() ?? '')
                .filter((name) => name !== ''),
            )}
          </span>
        </div>
      )}

      {children === undefined || children === null ? null : (
        <span className="gs-presence__actions" data-gs-scope="presence" data-gs-part="actions">
          {children}
        </span>
      )}
    </div>
  )
}

/* Presence. Every value comes from a token; nothing here is a literal colour.

   Specimen 4h draws the two pills and design/twins/4h.json measures ours
   against them. */

.gs-presence {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--gs-space-gap);

  font-family: var(--gs-type-body-font-family);
  color: var(--gs-color-ink);
}

/* -- the count ------------------------------------------------------------- */
/* A hole punched in the surface, the same idea as the score chip: dark fill,
   bright ring, the room's symbols in front and the live dot after. The drawing
   pads it tighter on the symbols' side than on the dot's. */
.gs-presence__count {
  display: flex;
  align-items: center;
  gap: var(--gs-space-gap);
  box-sizing: border-box;
  min-height: var(--gs-size-control-medium);
  margin: 0;
  padding: 0 var(--gs-space-inset) 0 var(--gs-space-2);
  width: max-content;

  background: var(--gs-color-edge);
  border: var(--gs-stroke-ui) solid var(--gs-color-edge-high);
  border-radius: var(--gs-radius-full);
}

.gs-presence__symbols { display: flex; }

/* Symbols, not avatars: four discs in the room's colours, ringed in the edge
   and overlapping by one step. They stand for the room, not for anybody. */
.gs-presence__symbol {
  box-sizing: border-box;
  inline-size: var(--gs-size-icon-control);
  block-size: var(--gs-size-icon-control);
  border: var(--gs-stroke-ui) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-full);
}

.gs-presence__symbol + .gs-presence__symbol { margin-inline-start: calc(-1 * var(--gs-space-2)); }

.gs-presence__symbol--player { background: var(--gs-color-player-solid); }
.gs-presence__symbol--opponent { background: var(--gs-color-opponent-solid); }
.gs-presence__symbol--warning { background: var(--gs-color-warning-solid); }
.gs-presence__symbol--positive { background: var(--gs-color-positive-solid); }

.gs-presence__words {
  display: inline-flex;
  align-items: baseline;
  gap: var(--gs-space-1);
}

.gs-presence__value {
  font-family: var(--gs-type-figure-font-family);
  font-size: var(--gs-type-figure-font-size);
  font-weight: var(--gs-type-figure-font-weight);
  font-variant-numeric: var(--gs-type-score-font-variant-numeric);
}

.gs-presence__label {
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
}

/* -- the room's own dot ---------------------------------------------------- */
/* It pulses, so it is motion. Reduced motion takes `--gs-motion-pulse` to 0ms
   and the pulse stops dead, which is `coach-mark`'s arrangement and is why no
   media query is written here: the token owns that decision in one place. The
   dot stays either way, and the accessible name says the room is live in
   words, so nothing depends on the movement. space.2 is the drawing's 8px. */
.gs-presence__live {
  flex: 0 0 auto;
  inline-size: var(--gs-space-2);
  block-size: var(--gs-space-2);
  border-radius: var(--gs-radius-full);
  background: var(--gs-color-positive);
  /* The loop itself is motion.css's: the dot carries data-gs-motion="pulse"
     and the drawing's own keyframe scales it 1 to 1.06 over the pulse token,
     which is how the drawing's live dots pulse (4f, 4h). This file used to
     fade the dot to .35 instead, which the drawing does nowhere. */
}

/* An empty room has no live dot to show, and a dot that pulsed over "nothing
   here yet" would be saying two different things at once. */
.gs-presence[data-gs-empty='true'] .gs-presence__live {
  background: var(--gs-color-muted);
  animation: none;
}

/* -- the people the host can name ------------------------------------------ */
/* A surface pill: the avatars stacked, and one sentence saying who they are.
   Each identity keeps its own accessible name; on screen only its avatar
   shows, because the sentence already says the names. */
.gs-presence__named {
  display: flex;
  align-items: center;
  gap: var(--gs-space-2);
  box-sizing: border-box;
  min-height: var(--gs-size-control-medium);
  padding: 0 var(--gs-space-3);

  background: var(--gs-color-surface);
  border: var(--gs-stroke-ui) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-full);
}

.gs-presence__list {
  display: flex;
  align-items: center;
  margin: 0;
  padding: 0;
  list-style: none;
}

.gs-presence__row {
  display: flex;
  align-items: center;
}

.gs-presence__row + .gs-presence__row { margin-inline-start: calc(-1 * var(--gs-space-2)); }

/* The avatar ringed in the edge at the control stroke, so the stack reads as
   one row of discs over whatever is behind it. */
.gs-presence__row .gs-identity[data-gs-size] .gs-identity__avatar,
.gs-presence__row .gs-identity__avatar {
  /* 24px discs, the drawing's, at any identity step: identity's own size rules
     outrank a plain descendant selector, which is how the stack grew to 40. */
  inline-size: var(--gs-size-icon-control);
  block-size: var(--gs-size-icon-control);
  box-sizing: border-box;
  border-width: var(--gs-stroke-ui);
  border-color: var(--gs-color-edge);
}

.gs-presence__row .gs-identity__text,
.gs-presence__row .gs-identity__presence {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  white-space: nowrap;
  clip-path: inset(50%);
  border: 0;
}

.gs-presence__summary {
  font-family: var(--gs-type-eyebrow-font-family);
  font-size: var(--gs-type-eyebrow-font-size);
  font-weight: var(--gs-type-eyebrow-font-weight);
}

.gs-presence__actions {
  display: flex;
  align-items: center;
  gap: var(--gs-space-2);
}
